WITH base AS (SELECT * FROM store_sales WHERE store_id IN (1, 3, 5) AND revenue > 2500), revenue_bucket_summary AS (SELECT CASE WHEN revenue >= 3200 THEN 'high' WHEN revenue >= 1300 THEN 'mid' ELSE 'low' END AS revenue_bucket, COUNT(revenue) AS revenue_count, COUNT(units) AS units_count FROM base GROUP BY CASE WHEN revenue >= 3200 THEN 'high' WHEN revenue >= 1300 THEN 'mid' ELSE 'low' END) SELECT revenue_bucket, units_count FROM revenue_bucket_summary ORDER BY revenue_bucket, units_count DESC
